<script setup>
import { computed,ref,watch,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { get } from '../services/api'
import { auth } from '../stores/auth'
import { entities,labels,statusLabels,actionLabels,cell,routeFor } from '../entities'
import LoadState from '../components/LoadState.vue'
import LookupSelect from '../components/LookupSelect.vue'
import ModerationDialog from '../components/ModerationDialog.vue'
const props=defineProps({type:String}),route=useRoute(),router=useRouter()
const definition=computed(()=>entities[props.type]),data=ref(null),busy=ref(false),error=ref(null),filters=ref({}),target=ref(null),countries=ref([]),brands=ref([]),categories=ref([])
let controller,version=0
const options={role:['customer','merchant','admin'],listing_type:['sale','rental'],publication_status:['draft','published','archived'],moderation_status:['clear','review','suspended'],users:['active','suspended'],merchants:['pending','approved','rejected','suspended'],shops:['draft','published','suspended'],vehicles:['available','rented','sold','other'],reservations:['pending','confirmed','active','completed','rejected','cancelled','expired'],orders:['pending','confirmed','fulfilled','cancelled'],payments:['initiated','pending','paid','failed','cancelled']}
const filterLabels={q:'Recherche',country_code:'Pays',city_id:'Ville',shop_id:'Boutique',merchant_id:'Professionnel',brand_id:'Marque',category_id:'Catégorie',listing_type:'Offre',publication_status:'Publication',moderation_status:'Modération',status:'Statut',role:'Rôle'}
function choices(key){if(key==='country_code')return countries.value.map(x=>({value:x.code,label:x.name}));if(key==='brand_id')return brands.value.map(x=>({value:x.id,label:x.name}));if(key==='category_id')return categories.value.map(x=>({value:x.id,label:x.label}));return (key==='status'?options[props.type]:options[key])?.map(value=>({value,label:statusLabels[value]||value}))}
async function load(){const v=++version;controller?.abort();controller=new AbortController();busy.value=true;error.value=null;data.value=null;filters.value={...route.query};try{const r=await get('/admin/'+props.type,route.query,controller.signal);if(v===version)data.value=r}catch(e){if(v===version&&!controller.signal.aborted)error.value=e}finally{if(v===version)busy.value=false}}
function apply(){router.push({path:'/'+props.type,query:Object.fromEntries(Object.entries({...filters.value,page:1}).filter(([,v])=>v!==''&&v!==null&&v!==undefined))})}
function page(n){router.push({query:{...route.query,page:n}})}
function actions(row){return definition.value.actions.filter(a=>{if(props.type==='users'&&row.id===auth.user?.id&&a==='suspend')return false;const status=row.status;return a==='suspend'?status!=='suspended':a==='reactivate'?status==='suspended':a==='approve'?['pending','rejected'].includes(status):a==='publish'?row.publication_status!=='published'||row.moderation_status==='suspended':true})}
function moderate(row,action){target.value={type:props.type,id:row.id,action,label:row.name||row.title||row.reference}}
watch(()=>[props.type,route.fullPath],load,{immediate:true})
get('/countries').then(r=>countries.value=r.data).catch(()=>{})
get('/brands').then(r=>brands.value=r.data).catch(()=>{})
get('/categories').then(r=>categories.value=r.data).catch(()=>{})
onBeforeUnmount(()=>{version++;controller?.abort()})
</script>
<template><div><div class="page-title"><div><span class="eyebrow">Administration globale</span><h1>{{ definition.title }}</h1></div><span class="badge">{{ data?.meta?.total ?? '—' }} résultats</span></div><p class="lead">{{ type==='payments'?'Paiements de démonstration uniquement. Aucun encaissement réel.':type==='receipts'?'Documents historiques immuables, y compris pour les administrateurs.':'Données serveur · Historique conservé · Aucun transfert de propriété.' }}</p><form class="filters" @submit.prevent="apply"><label>Recherche<input v-model="filters.q" maxlength="120" placeholder="Nom ou référence…"></label><label v-for="key in definition.filters" :key="key">{{ filterLabels[key] }}<LookupSelect v-if="['city_id','shop_id','merchant_id'].includes(key)" v-model="filters[key]" :kind="{city_id:'cities',shop_id:'shops',merchant_id:'merchants'}[key]" :country="filters.country_code"/><select v-else-if="choices(key)" v-model="filters[key]"><option value="">Tous</option><option v-for="option in choices(key)" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-else v-model="filters[key]" type="number" min="1" placeholder="Identifiant"></label><button>Filtrer</button><button type="button" class="secondary" @click="router.push({path:'/'+type,query:{}})">Réinitialiser</button></form><p v-if="route.query.user_id || route.query.vehicle_id" class="badge">Périmètre : {{ route.query.user_id?'client '+route.query.user_id:'véhicule '+route.query.vehicle_id }}</p><LoadState :busy="busy" :error="error" :empty="data && !data.data.length" @retry="load"><div v-if="data" class="table-wrap"><table><thead><tr><th v-for="column in definition.columns" :key="column">{{ labels[column] }}</th><th v-if="type!=='activity'">Actions</th></tr></thead><tbody><tr v-for="row in data.data" :key="row.id"><td v-for="(column,index) in definition.columns" :key="column"><div v-if="index===0" class="identity"><img v-if="row.avatar_url||row.logo_url||row.primary_image?.url" :src="row.avatar_url||row.logo_url||row.primary_image?.url" alt="" @error="$event.target.style.display='none'"><RouterLink v-if="type!=='activity'" :to="routeFor(type,row)">{{ cell(row,column) }}</RouterLink><span v-else>{{ cell(row,column) }}</span></div><span v-else :class="{'badge':column.includes('status')||column==='is_demo'}">{{ cell(row,column) }}</span></td><td v-if="type!=='activity'"><div class="row-actions"><RouterLink :to="routeFor(type,row)">Voir →</RouterLink><button v-for="action in actions(row)" :key="action" class="text-button" @click="moderate(row,action)">{{ actionLabels[action] }}</button></div></td></tr></tbody></table></div></LoadState><nav v-if="data?.meta" class="pagination" aria-label="Pagination"><span>{{ data.meta.total }} résultats · Page {{ data.meta.current_page }} / {{ data.meta.last_page }}</span><button class="secondary" :disabled="data.meta.current_page<=1 || busy" @click="page(data.meta.current_page-1)">Précédent</button><button class="secondary" :disabled="data.meta.current_page>=data.meta.last_page || busy" @click="page(data.meta.current_page+1)">Suivant</button></nav><ModerationDialog :target="target" @close="target=null" @done="load"/></div></template>
